import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as e,af as t}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const C=JSON.parse('{"title":"GLM Coding Plan 术语表","description":"解释套餐、指定工具、Coding 端点、积分和次级调度。不教逐步配置。","frontmatter":{"title":"GLM Coding Plan 术语表","description":"解释套餐、指定工具、Coding 端点、积分和次级调度。不教逐步配置。","domain":"product","tags":["coding-plan"],"role":"glossary"},"headers":[],"relativePath":"zh/products/glm-coding/glm-coding-glossary.md","filePath":"zh/products/glm-coding/glm-coding-glossary.md","lastUpdated":1787107158000}'),s={name:"zh/products/glm-coding/glm-coding-glossary.md"};function r(d,o,p,l,i,g){return e(),a("div",null,[...o[0]||(o[0]=[t(`<h1 id="glm-coding-plan-术语表" tabindex="-1">GLM Coding Plan 术语表 <a class="header-anchor" href="#glm-coding-plan-术语表" aria-label="Permalink to &quot;GLM Coding Plan 术语表&quot;">​</a></h1><p>不教操作。把容易撞车的名字分开后，速查表里的端点和积分才有位置。选哪扇门看 <a href="./">学习地图</a>。</p><h2 id="概念关系" tabindex="-1">概念关系 <a class="header-anchor" href="#概念关系" aria-label="Permalink to &quot;概念关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>智谱清言 / Z.ai     聊天产品（#74）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>BigModel 标准 API    /api/paas/v4 按量，自建应用走这里</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>GLM Coding Plan      订阅：只给指定编程工具供 GLM</span></span>
<span class="line"><span>        ├── Coding Agent（Claude Code、Cursor …）优先调度</span></span>
<span class="line"><span>        ├── 通用 Agent（OpenClaw …）次级调度</span></span>
<span class="line"><span>        └── Coding Tool Helper     装载器，不是 Agent</span></span></code></pre></div><h2 id="glm-coding-plan" tabindex="-1">GLM Coding Plan <a class="header-anchor" href="#glm-coding-plan" aria-label="Permalink to &quot;GLM Coding Plan&quot;">​</a></h2><p><strong>是什么：</strong> 智谱面向 AI 编码场景的订阅套餐。官方原文：「专为 AI 编码打造的订阅套餐」（<a href="https://docs.bigmodel.cn/cn/coding-plan/overview" target="_blank" rel="noreferrer">overview</a>）。</p><p><strong>为什么需要：</strong> 在 Claude Code / Cursor 等现成助手里用 GLM，按套餐积分走，而不是按标准 API 逐 Token 付。</p><p><strong>不是什么：</strong> 不是清言，不是 Z.ai 聊天，不是智谱第一方终端 Agent，也不是开放平台资源包。</p><h2 id="指定工具" tabindex="-1">指定工具 <a class="header-anchor" href="#指定工具" aria-label="Permalink to &quot;指定工具&quot;">​</a></h2><p><strong>是什么：</strong> 官方列出的 Coding Agent 与通用 Agent 名单（<a href="https://docs.bigmodel.cn/cn/coding-plan/tool/others" target="_blank" rel="noreferrer">tool/others</a>）。名单外调用 API，不可享用套餐额度。</p><p><strong>为什么需要：</strong> 编码 Agent 消耗高。平台用名单 + 专用端点，把套餐容量留在编程场景。</p><p><strong>不是什么：</strong> 不是「任何能填 Base URL 的客户端」。官网体验中心也不算。</p><h2 id="coding-端点" tabindex="-1">Coding 端点 <a class="header-anchor" href="#coding-端点" aria-label="Permalink to &quot;Coding 端点&quot;">​</a></h2><p><strong>是什么：</strong> 套餐专用的 Anthropic / OpenAI Compatible URL。国内分别是 <code>https://open.bigmodel.cn/api/anthropic</code> 与 <code>https://open.bigmodel.cn/api/coding/paas/v4</code>。</p><p><strong>为什么需要：</strong> 同一把 Key 打到 <code>/api/paas/v4</code> 会走标准计费或报余额不足，看起来像「套餐没生效」。</p><p><strong>不是什么：</strong> 不是海外 <code>api.z.ai</code> 的同一主机。国内 / 海外两套站点，不要混。</p><h2 id="积分" tabindex="-1">积分 <a class="header-anchor" href="#积分" aria-label="Permalink to &quot;积分&quot;">​</a></h2><p><strong>是什么：</strong> 套餐同时设每 5 小时和每周上限。模型按 Token × 抵扣系数 / 10000 扣；MCP 按次数 × Output 系数扣。</p><p><strong>为什么需要：</strong> 用积分而不是裸 Token，才能在高峰 / 非高峰、不同模型和 MCP 之间做同一套账。</p><p><strong>不是什么：</strong> 不是账户现金余额，也不是开放平台资源包。额度耗尽后等刷新，官方写明不会改扣其它余额。</p><h2 id="次级调度" tabindex="-1">次级调度 <a class="header-anchor" href="#次级调度" aria-label="Permalink to &quot;次级调度&quot;">​</a></h2><p><strong>是什么：</strong> OpenClaw 等通用 Agent 的资源策略。overview 原文：采用<strong>次级调度</strong>与尽力交付；Coding Agent 任务享有资源抢占优先权；高负载下触发动态排队、限流等公平使用策略。</p><p><strong>为什么需要：</strong> 大部分用户在 Coding Agent 场景；通用 Agent 分享同一池子时，编程请求优先。</p><p><strong>不是什么：</strong> 不是「官方不支持 OpenClaw」。支持，但保障级别低于 Claude Code。</p><h2 id="团队套餐-key" tabindex="-1">团队套餐 Key <a class="header-anchor" href="#团队套餐-key" aria-label="Permalink to &quot;团队套餐 Key&quot;">​</a></h2><p><strong>是什么：</strong> 团队版每位成员在「团队编程套餐」里拿到的专用调用凭证。与平台其他 API Key 相互独立（<a href="https://docs.bigmodel.cn/cn/coding-plan/team" target="_blank" rel="noreferrer">team</a>）。</p><p><strong>为什么需要：</strong> 席位、账单、超额按量按组织结算。混用个人 Key 会打到错误的额度池。</p><p><strong>不是什么：</strong> 不是主管理员账号自带的那把平台 Key。主管理员默认不占席位，要用额度得给自己分配席位。</p><h2 id="coding-tool-helper" tabindex="-1">Coding Tool Helper <a class="header-anchor" href="#coding-tool-helper" aria-label="Permalink to &quot;Coding Tool Helper&quot;">​</a></h2><p><strong>是什么：</strong> 命令行助手，npm 包 <code>@z_ai/coding-helper</code>，二进制 <code>coding-helper</code> / <code>chelper</code>。把套餐装进 Claude Code、OpenCode、Crush、Factory Droid。</p><p><strong>为什么需要：</strong> 免手改 <code>settings.json</code> 和 MCP。</p><p><strong>不是什么：</strong> 不是编码 Agent，也不覆盖 Cursor 等其余指定工具。</p><h2 id="服务端模型映射" tabindex="-1">服务端模型映射 <a class="header-anchor" href="#服务端模型映射" aria-label="Permalink to &quot;服务端模型映射&quot;">​</a></h2><p><strong>是什么：</strong> Claude Code 配好套餐后，界面仍可能显示 Claude 的 Opus / Sonnet / Haiku 名称，实际由服务端映射到 GLM（<a href="https://docs.bigmodel.cn/cn/coding-plan/tool/claude" target="_blank" rel="noreferrer">tool/claude</a>）。</p><p><strong>为什么需要：</strong> 让现有 Claude Code 工作流少改界面。硬编码映射会在套餐默认模型升级时掉队。</p><p><strong>不是什么：</strong> 不是你真的在调 Anthropic。<code>/status</code> 里应能看到 <code>glm-*</code>。</p><h2 id="国内站-vs-海外站" tabindex="-1">国内站 vs 海外站 <a class="header-anchor" href="#国内站-vs-海外站" aria-label="Permalink to &quot;国内站 vs 海外站&quot;">​</a></h2><p><strong>是什么：</strong> 国内 <code>docs.bigmodel.cn</code> + <code>open.bigmodel.cn</code>；海外 <code>docs.z.ai/devpack</code> + <code>api.z.ai</code>。Helper 的套餐标识分别是 <code>glm_coding_plan_china</code> 与 <code>glm_coding_plan_global</code>。</p><p><strong>为什么需要：</strong> Key、端点、适用工具名单都不完全相同。</p><p><strong>不是什么：</strong> 不是同一控制台的两个皮肤。清言 / Z.ai 也不是这两个编码控制台。</p>`,40)])])}const b=n(s,[["render",r]]);export{C as __pageData,b as default};
